from dataclasses import dataclass


@dataclass(frozen=True)
class Bar:
    day: str
    open: float
    high: float
    low: float
    close: float


def run(bars, signals, cash=1_000_000.0):
    """signals[i] is 1 (be long) or 0 (be flat), known after the close of bar i."""
    shares = 0.0
    equity = []
    for i, bar in enumerate(bars):
        if i:
            want = signals[i - 1]
            if want and not shares:
                shares, cash = cash / bar.open, 0.0
            elif not want and shares:
                shares, cash = 0.0, shares * bar.open
        equity.append(cash + shares * bar.close)
    return equity

