import math


def summarize(returns):
    if not returns:
        return None
    n = len(returns)
    low = sorted(returns)[:max(1, n // 20)]
    return {"n_days": n, "cagr": math.prod(1 + r for r in returns) ** (252 / n) - 1,
            "win_rate": sum(r > 0 for r in returns) / n, "worst": sum(low) / len(low)}

