#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Jitter {
    None,
    Full,
    Equal,
    Decorrelated,
}

pub struct Policy {
    pub max_attempts: u32,
    pub base_ms: u64,
    pub cap_ms: u64,
    pub jitter: Jitter,
    pub retry_statuses: &'static [u16],
}

pub fn download() -> Policy {
    Policy {
        max_attempts: 3,
        base_ms: 100,
        cap_ms: 5_000,
        jitter: Jitter::Full,
        retry_statuses: &[429, 500, 502, 503, 504],
    }
}

pub fn upload() -> Policy {
    Policy {
        max_attempts: 7,
        base_ms: 350,
        cap_ms: 45_000,
