        for x in kept
    ]

CHARS_PER_SECOND = 3.5
TAKES = 4


def make_sheet(lines):
    scenes = {}
    for line in lines:
        scenes.setdefault(line["scene"], []).append(line)
    sheet = []
    for scene in sorted(scenes, reverse=True):
        for line in sorted(scenes[scene], key=lambda entry: entry["no"]):
            if line["speaker"] == "MOSS":
                continue
            cue = "K%02d-%03d" % (scene, 10 * line["no"])
            seconds = round(sum(1 for c in line["text"] if not c.isspace()) / CHARS_PER_SECOND, 2)
            sheet.append(dict(cue=cue, speaker=line["speaker"], text=line["text"], seconds=seconds, takes=TAKES))
    return sheet

