#pragma once
#include <stdbool.h>
#include <stdint.h>

#define RX_BUF_SIZE 384u

typedef struct {
    volatile uint8_t buf[RX_BUF_SIZE];
    volatile uint16_t head; /* written by the ISR only */
    volatile uint16_t tail; /* written by the main loop only */
} ring_t;

bool ring_put(ring_t *r, uint8_t byte);
bool ring_get(ring_t *r, uint8_t *byte);
uint16_t ring_count(const ring_t *r);

files.src/ring.c:
#include "ring.h"

bool ring_put(ring_t *r, uint8_t byte)
{
    uint16_t next = (r->head + 1u) % RX_BUF_SIZE;

    if (next == r->tail)
        return false;
    r->buf[r->head] = byte;
    r->head = next;
    return true;
}

bool ring_get(ring_t *r, uint8_t *byte)
{
    if (r->tail == r->head)
        return false;
    *byte = r->buf[r->tail];
    r->tail = (r->tail + 1u) % RX_BUF_SIZE;
    return true;
}

uint16_t ring_count(const ring_t *r)
{
    return (r->head + RX_BUF_SIZE - r->tail) % RX_BUF_SIZE;
}

