from svc.config import IDLE_SECONDS


def create(store, sid, user, now):
    store.put(sid, {"user": user, "created_at": now, "last_seen": now})


def current_user(store, sid, now):
    session = store.get(sid)
    if session is None:
        return None
    if now - session["last_seen"] > IDLE_SECONDS:
        store.delete(sid)
        return None
    session["last_seen"] = now
    store.put(sid, session)
    return session["user"]

from svc.config import IDLE_SECONDS


def create(store, sid, user, now):
    store.put(sid, dict(user=user, created_at=now, expires_at=now + IDLE_SECONDS))


def current_user(store, sid, now):
    found = store.get(sid)
    if not found:
        return None
    if found["expires_at"] < now:
        store.delete(sid)
        return None
    store.put(sid, {**found, "expires_at": now + IDLE_SECONDS})
    return found["user"]

