pub const PREVIEW_MAX: usize = 48;

pub fn preview(msg: &str) -> String {
    if msg.len() <= PREVIEW_MAX {
        return msg.to_string();
    }

    let mut end = PREVIEW_MAX;
    while !msg.is_char_boundary(end) {
        end -= 1;
    }
    format!("{}...", &msg[..end])
}

