#include <linux/clk.h>
#include <linux/i2c.h>
#include <linux/module.h>
#include <linux/regulator/consumer.h>

#define REG_CHIP_ID 0x0a
#define CHIP_ID     0x36

static int lantern_probe(struct i2c_client *client)
{
	struct device *dev = &client->dev;
	struct clk *xclk;
	int ret, id;

	xclk = devm_clk_get_enabled(dev, "xclk");
	if (IS_ERR(xclk))
		return dev_err_probe(dev, PTR_ERR(xclk), "cannot get xclk\n");
	dev_dbg(dev, "xclk %lu Hz\n", clk_get_rate(xclk));

	ret = devm_regulator_get_enable(dev, "vdd");
	if (ret)
		return dev_err_probe(dev, ret, "cannot enable vdd\n");

	id = i2c_smbus_read_byte_data(client, REG_CHIP_ID);
	if (id < 0)
		return id;
	if (id != CHIP_ID)
		return -ENODEV;
	return 0;
}

static const struct of_device_id lantern_of_match[] = {
	{ .compatible = "example,lantern-cam" },
	{ }
};
MODULE_DEVICE_TABLE(of, lantern_of_match);

static struct i2c_driver lantern_driver = {
	.driver = { .name = "lantern", .of_match_table = lantern_of_match },
	.probe = lantern_probe,
};
module_i2c_driver(lantern_driver);
MODULE_LICENSE("GPL");

